static const work_item POISON = { .kind = ITEM_STOP };

/* producer, after the last real item: */
queue_push(&q, POISON);
pthread_cond_signal(&q.cond);

/* consumer: */
work_item it;
while (queue_pop(&q, &it) == 0) {     /* blocks on the cond var */
    if (it.kind == ITEM_STOP) break;  /* drain finished */
    process(&it);
}
